scenario.irule:
when SA_PICKED { set ::source_addr [XLAT::src_addr]; set ::source_port [XLAT::src_port]; set ::source_ranges [XLAT::src_nat_valid_range]; log local0. "source=$::source_addr:$::source_port ranges=$::source_ranges" }
when CLIENT_DATA { set ::listener [XLAT::listen -hairpin -single-connection 30 {
 proto TCP
 bind -ip 198.51.100.20 -port 4000
 server 10.0.0.2 80
 allow 10.0.0.2 0
 inherit-vs /Common/app_vs
 }]; log local0. "listener=$::listener" }
when HTTP_REQUEST { set ::source_config [XLAT::src_config]; set ::listener_lifetime [XLAT::listen_lifetime $::listener]; set ::listener_updated [XLAT::listen_lifetime $::listener 45]; set ::reservation [XLAT::src_endpoint_reservation create -pool /Common/snat 10.0.0.2 50000 TCP 120]; set ::translation_address [lindex $::reservation 0]; set ::translation_port [lindex $::reservation 1]; set ::reservation_found [XLAT::src_endpoint_reservation get $::translation_address $::translation_port /Common/snat TCP]; set ::reservation_updated [XLAT::src_endpoint_reservation update_lifetime $::translation_address $::translation_port /Common/snat TCP 300]; log local0. "config=$::source_config lifetime=$::listener_lifetime/$::listener_updated reservation=$::reservation found=$::reservation_found renewed=$::reservation_updated" }
